insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('3eedda97-43cc-433a-95d4-4bf4878958cd', 'de', 'Sie ist voll dabei, und die Stimmung ist stark. Welcher selbstverständliche Abschluss hält den Schwung?', '["„Das machen wir noch mal. Gib mir deine Nummer.“", "„Hättest du Interesse, mich wiederzusehen?“", "„Wärst du offen dafür, mal was zu machen?“", "„Ich glaub, wir sollten uns vielleicht mal treffen?“"]'::jsonb, 'Geh davon aus, dass ihr Interesse da ist, und schlag den Plan direkt vor.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('4051e636-695d-4534-936e-1f530668bf29', 'de', 'Warum wird ein Gespräch einseitig, wenn du zu viele Fragen hintereinander stellst?', '["Sie muss die meiste Arbeit machen", "Es fühlt sich wie Ausfragen an statt wie ein Austausch", "Sie zeigen, dass du aufmerksam bist"]'::jsonb, 'Fragen am laufenden Band schaffen ein Ungleichgewicht: Einer gibt, der andere nimmt.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('4533a8d2-717d-49b4-b4a9-c89b28985777', 'de', 'Sie sagt: „Ich bin gerade aus Japan zurück.“ Was könntest du darauf sagen?', '["Ihr von deinen eigenen Reisen erzählen", "Fragen: „Was hat dir in Japan am besten gefallen?“", "Das Thema wechseln und fragen, wo sie wohnt", "Sie dafür loben, dass sie reist"]'::jsonb, 'Wenn du an ihr Detail anknüpfst, vertieft sich das Gespräch ganz natürlich.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('48b2d089-1b51-4e26-9f2f-517c02891e1b', 'de', 'Welches Verhalten zeigt nonverbal, dass du dabei bist?', '["Dich ihr zuwenden, während sie spricht", "Durchgehend neutrale Miene", "Natürlicher Blickkontakt", "Dezentes Nicken an wichtigen Stellen"]'::jsonb, 'Zuwendung, Blickkontakt und Bewegungen, die auf sie reagieren, zeigen Präsenz.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('497c00d6-116b-4bf7-9ccf-9fdbef04ef82', 'de', 'Sie antwortet knapp zu ihrer Familie, und die Energie sinkt. Was könntest du als Nächstes tun?', '["Noch eine Frage zu ihrer Familie stellen", "Locker umlenken: „Und, wie schmeckt dein Essen?“", "Dich für den peinlichen Moment entschuldigen", "Sie fragen, warum sie so kurz geantwortet hat"]'::jsonb, 'Lenk ruhig auf neutrales Terrain um, damit der Schwung ohne Druck zurückkommt.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('4cd2af01-a10e-4c9e-b164-6c82a959ca1f', 'de', 'Warum schwächt es die Verbindung, wenn du unbedingt recht behalten willst?', '["Das Gespräch wird zum Wettkampf", "Es zeigt, dass dir Rechthaben wichtiger ist als die Verbindung", "Es zeigt, dass du sozial aufmerksam bist", "Sie fühlt sich im Unrecht statt einfach anders"]'::jsonb, 'Nicht die Meinungsverschiedenheit sorgt für Spannung, sondern der Drang, recht zu behalten.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('4d5ba9c1-712a-4d9d-b8a1-4ffec08ad96c', 'de', 'Welche Einstellung macht es möglich, zuzuhören, um zu verstehen?', '["Schlagfertige Antworten vorbereiten", "Ganz da sein, ohne vorauszuplanen", "Darauf achten, wie deine Geschichten zu ihren passen", "Schnell reagieren, um die Energie zu halten"]'::jsonb, 'Präsenz heißt, vorgeplante Antworten loszulassen.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('4e01d376-3513-4958-b45f-3cbac7198e67', 'de', 'Ihr hattet ein tolles Gespräch über ihre anstehende Portugalreise. Zeit zu gehen. Was könntest du sagen?', '["„Schön, mit dir zu reden. Hab einen schönen Tag.“", "„China klingt toll. Du musst mir erzählen, wie’s war.“", "„Gute Reise, wann immer du fährst.“"]'::jsonb, 'Hör mit einem konkreten Rückbezug auf. Das schafft einen roten Faden und einen natürlichen Grund, dich wieder zu melden.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('4e138ced-bcd3-4f4b-9394-d046b4bd81e7', 'de', 'Sie will ein Café ausprobieren, das du empfohlen hast. Gute Abschlüsse mit wenig Druck?', '["„Lass uns diese Woche zusammen hingehen. Hast du Samstag Zeit?“", "„Ich schick dir die Adresse. Was ist deine Nummer?“", "„Sag mir Bescheid, wie’s war, wenn du dort warst.“"]'::jsonb, 'Bitten mit wenig Druck senken die Abwehr. Halt sie klein, damit sich ein Ja natürlich anfühlt.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('52c57688-6476-42cc-9677-4cb5e66512fd', 'de', 'Sie fragt: „Warum ist deine letzte Beziehung zu Ende gegangen?“ Welche Antwort ist am geerdetsten?', '["„Sie hat mich sehr verletzt, und ich hab immer noch daran zu knabbern.“", "„Es war toxisch und hat mich echt fertiggemacht.“", "„Wir wollten verschiedene Dinge, und ich hab dabei gelernt, was mir heute wichtiger ist.“"]'::jsonb, 'Diese Antwort ist ehrlich und zeigt trotzdem Abstand. Sie weckt Neugier, keine Sorge.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('535c49aa-9750-45dd-9796-69f61c22aedf', 'de', 'Welches Verhalten zeigt, dass jemand zuhört, um zu antworten, statt um zu verstehen?', '["Aufgreifen, was sie erzählt hat", "Schnell mit Ratschlägen kommen", "Sie unterbrechen, bevor sie fertig ist", "Antworten, die nichts mit ihrem letzten Punkt zu tun haben"]'::jsonb, 'Dieses Verhalten zeigt, dass es um Auftritt oder Kontrolle geht statt ums Verstehen.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('58d8c403-8e7d-4168-b8ba-758c4dff889c', 'de', 'Sie sagt: „Ich bin gerade aus Japan zurück.“ Was könntest du darauf sagen?', '["Ihr von deinen eigenen Reisen erzählen", "Fragen: „Was hat dir in Japan am besten gefallen?“", "Das Thema wechseln und fragen, wo sie wohnt", "Sie dafür loben, dass sie reist"]'::jsonb, 'Wenn du an ihr Detail anknüpfst, vertieft sich das Gespräch ganz natürlich.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('59ddb591-0f25-456d-abef-ddcf1bc55c9f', 'de', 'Sie erzählt von einer lustigen Reisepanne. Was könnte deine Geschichte als Antwort tun?', '["Mit einer ähnlich lustigen Anekdote mithalten", "Deine komplette Reisegeschichte erzählen", "Zu einem ganz anderen Thema springen", "Einen Rat geben, statt etwas zu erzählen"]'::jsonb, 'Halt es kurz und klar, um ihre Energie aufzugreifen und eine Verbindung aufzubauen.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('5def4588-2c49-4e7d-a78b-6de3a668455b', 'de', 'Warum bringen zu viele Fragen das Gespräch ins Ungleichgewicht?', '["Du holst Informationen raus, ohne selbst etwas beizutragen", "Fragen setzen sie unter Druck, etwas zu bieten und zu unterhalten", "Beides"]'::jsonb, 'Fragen am laufenden Band schaffen ein Ungleichgewicht: Einer gibt, der andere nimmt.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('6309d2eb-7004-43f3-99ec-c276acb5ec61', 'de', 'Sie hält intensiven Blickkontakt und fragt nach. Was zeigt das?', '["Sie ist abgelenkt und will das Gespräch beenden", "Das Gespräch braucht erst noch mehr Smalltalk", "Sie ist höflich, hat aber kein Interesse", "Sie bringt sich ein, und der Moment ist reif für den Abschluss"]'::jsonb, 'Aktive Neugier und positive Körpersprache zeigen, dass der Moment reif für den Abschluss ist.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('65941383-8920-456d-9564-8f938de86fed', 'de', 'Was hilft dir, anderer Meinung zu sein, ohne die Verbindung zu verlieren?', '["Deine Sicht als absolute Wahrheit darstellen", "Fragen stellen, wie sie zu ihrer Meinung kommt", "Im Ton ruhig bleiben", "Beide Sichtweisen nebeneinander stehen lassen"]'::jsonb, 'Die Verbindung bleibt, wenn ihr Unterschiede erkundet, statt sie abzuwerten.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('66cbe1b3-1585-4d3f-b00f-bb1fcf3143d3', 'de', 'Was passiert, wenn du weitermachst, ohne auf ihren Punkt einzugehen?', '["Du klingst gehetzt", "Es wirkt, als hättest du sie vielleicht nicht verstanden", "Es gibt weniger Gesprächsthemen", "Es bremst den Schwung"]'::jsonb, 'Würdigen zeigt Verständnis. Mach das, bevor du die nächste Frage stellst.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('674acf71-26d4-428e-aa33-571e27f0d7d7', 'de', 'Warum fühlt sich das Anknüpfen an Fäden natürlicher an als Themensprünge?', '["Es ist so, wie Freunde wirklich miteinander reden", "Das Gespräch baut auf sich selbst auf, statt beliebig zu wirken", "Sie fühlt sich gehört, weil du auf das eingehst, was sie sagt", "B und C"]'::jsonb, 'Anknüpfen schafft Fluss: Jede Antwort baut auf der vorigen auf.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('68abae72-376e-4c38-bd5f-a63ad5d4ed56', 'de', 'Sie erzählt kurz von einer stressigen Deadline, die sie gerade geschafft hat. Deine Reaktion?', '["Erst würdigen, dann von einer ähnlichen Herausforderung im Job erzählen, die du gemeistert hast", "Sofort Karrieretipps geben", "Zu deinen Wochenendplänen wechseln"]'::jsonb, 'Greif ihre Energie mit einer kurzen, passenden Geschichte auf, um eine Verbindung aufzubauen.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('6a3257d1-17bb-4df3-b9ca-c907755b7988', 'de', 'Was macht am Anfang eines Gesprächs eine gute Geschichte aus?', '["Einen bestimmten Moment mit emotionaler Wirkung auswählen", "So viele Details wie möglich einbauen", "Alles genau so erzählen, wie du es in Erinnerung hast", "Sie lang machen, um Tiefe zu zeigen"]'::jsonb, 'Ein knapper Ausschnitt dessen, was wichtig war, schafft schneller Verbindung als die ganze Geschichte.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('72a6b099-3278-4a37-8a82-51225280d333', 'de', 'Was schafft positive emotionale Anker?', '["Echtes Lachen, kein höfliches, sondern echte Freude", "Würdigen, also anerkennen, was ihr wichtig ist", "Neugier, die sie anders über sich nachdenken lässt", "Alle oben genannten"]'::jsonb, 'Würdigen, Neugier und Lachen bringen Gefühle in Bewegung.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('75148042-557e-4fcd-b9cf-a733e31a8702', 'de', 'Sie sagt: „Ich hab gerade meine Schwester in Portland besucht.“ Was könntest du darauf sagen?', '["„Reist du viel?“", "„Schön, dass du so ein enges Verhältnis zu deiner Schwester hast. Was habt ihr so gemacht?“", "„Portland ist toll. Warst du schon mal in Seattle?“", "„Wie lange warst du weg?“"]'::jsonb, 'Würdige erst, was sie erlebt hat, um Verständnis zu zeigen, bevor du darauf aufbaust.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('75dbf155-f762-4c46-a881-ee4691d19f29', 'de', 'Mit welcher Einstellung kommst du insgesamt besser zum Abschluss?', '["„Ich muss was festmachen.“", "„Daraus muss was werden.“", "„Jetzt oder nie.“", "„Lass uns einen kleinen Schritt weitergehen.“"]'::jsonb, 'Kleine Schritte senken die Abwehr. Halt deine Bitten klein, damit sich ein Ja natürlich anfühlt.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('76af82d7-0b8b-4c02-ad43-4cff911e6e4f', 'de', 'Mit welcher Einstellung verabschiedest du dich insgesamt besser?', '["Auf Fäden achten, die du weiterspinnen kannst", "Auf gutes Timing hoffen", "Versuchen, in Erinnerung zu bleiben", "Schnell aufhören, um Peinlichkeit zu vermeiden"]'::jsonb, 'Wenn du an einen Faden anknüpfst, habt ihr einen natürlichen Grund, wieder Kontakt aufzunehmen.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('79854e99-6c36-4456-94b9-a4a09f901b6e', 'de', 'Warum schafft Würdigen psychologische Sicherheit?', '["Menschen fühlen sich mit dem, was sie erleben, anerkannt und verstanden", "Es zeigt emotionale Intelligenz und Empathie", "Würdigen gibt Menschen das Gefühl, wichtig und geschätzt zu sein"]'::jsonb, 'Wenn sie sich verstanden fühlt, öffnet sie sich ganz natürlich.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('7f4038e9-35fa-4928-b87c-513fe0b81ce9', 'de', 'Sie erwähnt einen stressigen Tag. Was solltest du vermeiden?', '["Sagen: „Hier kann ich nach einem langen Tag immer gut abschalten.“", "Fragen: „Was hat deinen Tag so stressig gemacht?“", "Sagen: „Du wirkst, als könntest du gut mit Stress umgehen.“"]'::jsonb, 'Verbinde dich mit positiven Gefühlen. Quetsch sie nicht über ihren Stress aus.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('8105c1a4-951f-4041-9374-fb7c65a70dca', 'de', 'Welche Fäden bietet dir „Ich bin Anwältin“?', '["Ihre genaue Rolle und ihre Aufgaben", "In welchem Rechtsgebiet sie arbeitet", "Ihre Berufserfahrung und ihren Werdegang", "Alle oben genannten"]'::jsonb, 'An einem Faden anknüpfen heißt, ihr Thema zu vertiefen. Frag konkret nach dem, was sie erwähnt hat.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('8389bf63-7797-4fed-8bf2-0f7cb7b996c7', 'de', 'Das Gespräch läuft gut, und sie lacht. Was könntest du sagen, um ganz selbstverständlich zum Abschluss zu kommen?', '["„Hättest du vielleicht mal Lust auf einen Kaffee?“", "„Ich weiß nicht, aber vielleicht könnten wir mal was machen?“", "„Willst du Nummern tauschen?“", "„Lass uns einen Kaffee trinken gehen. Was ist deine Nummer?“"]'::jsonb, 'Sag den nächsten Schritt selbstbewusst als Tatsache, statt um Erlaubnis zu fragen.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('8424db00-09f4-4aa8-b16b-d90b7a683c0b', 'de', 'Warum verringern lange Monologe die Anziehung?', '["Sie klingen einstudiert", "Sie nehmen ihr die Chance, sich einzubringen", "Sie bremsen das Gespräch", "Sie verraten zu viel"]'::jsonb, 'Wenn sie nichts beitragen kann, bringt sie sich weniger ein. Lass ihr Raum, etwas zu erzählen.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('8578c723-b332-450d-8dd1-4eaad1b6150b', 'de', 'Warum solltest du deine Geschichte mit ihrer Welt verknüpfen?', '["Es entsteht ein gemeinsamer Austausch statt zweier Geschichten nebeneinander", "Es zeigt, dass du die Geschichte nutzt, um sie zu verstehen", "Es verhindert, dass das Gespräch auseinanderfällt", "Alle oben genannten"]'::jsonb, 'Durch den Bezug wird die Geschichte zu einem Weg zur Verbindung, nicht nur zu einem Auftritt.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('87339858-15ab-4a2b-89af-d6a42cafac7a', 'de', 'Was bewirken Sätze, mit denen du sie würdigst?', '["Sie zeigen, dass ihre Worte wirklich bei dir angekommen sind", "Sie schaffen Raum für einen echteren Austausch", "Sie zeigen Selbstbewusstsein und emotionale Aufmerksamkeit", "Sie halten sie im Moment, mit dem Gefühl, verstanden zu werden"]'::jsonb, 'Wenn du auf ihre Worte eingehst, zeigst du, dass du sie gehört hast, und das lädt sie ein, mehr zu erzählen.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('97b34e22-5615-4aa3-bf23-73f5718f67c6', 'de', 'Was hilft, damit eine Geschichte Verbindung schafft, statt in einer Sackgasse zu enden?', '["Damit enden, wie beeindruckend das Ergebnis war", "Fragen, wie sie zu der Situation steht", "Die Geschichte mit etwas verbinden, das sie schon erwähnt hat"]'::jsonb, 'Geschichten verbinden, wenn sie ihre Welt ins Gespräch holen.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('97e7b932-511e-48e1-bf8b-9b0e49bd18f9', 'de', 'Sie redet, und du merkst, dass du schon deine Antwort planst. Was solltest du tun?', '["Schnell fertig planen und dann wieder zuhören", "Aufhören zu planen und sofort wieder ganz bei ihren Worten sein", "Sie bitten, das Letzte zu wiederholen, weil du abgeschweift bist"]'::jsonb, 'Bemerk, dass du abschweifst, und hol deine Aufmerksamkeit sofort zurück zu ihren Worten und ihrem Ton.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('998825a4-01bc-40bc-9219-b9e8a227feb8', 'de', 'Nachdem du eine andere Meinung gesagt hast, spürst du Spannung. Wie lenkst du am saubersten um?', '["Sanfter im Ton werden und nach ihrer Erfahrung fragen", "Mit noch mehr Beweisen nachlegen", "Dich dafür entschuldigen, dass du anderer Meinung bist"]'::jsonb, 'Wechsel vom Beweisen zum Verstehen. Frag lieber nach ihrer Erfahrung.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('9a3ada69-efcb-4e14-96d0-7d4c087e2d2a', 'de', 'Was tragen Beobachtungen und Aussagen vor allem zum Gespräch bei?', '["Sie gleichen den Austausch aus", "Sie zeigen deine eigene Sicht", "Sie verlangen von ihr eine Antwort"]'::jsonb, 'Sie machen das Gespräch zu etwas Gemeinsamem und Warmem.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('9b82f398-1878-449a-baf9-24e1e9ec6c0d', 'de', 'Warum schafft es Verbindung, Verarbeitetes zu teilen?', '["Es zeigt Selbstreflexion und persönliche Entwicklung", "Es zeigt Verletzlichkeit, ohne sie emotional zu belasten", "Es lädt zu Nähe ein, ohne dass sie sich verpflichtet fühlt zu helfen", "Alle oben genannten"]'::jsonb, 'Verarbeitete Erlebnisse laden zu Verbindung ein, nicht dazu, dass sie sich um dich kümmern muss.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('9bb0ed54-392a-4aab-9aed-715508c1df96', 'de', 'Du siehst einen Film anders als sie. Sie wirkt leidenschaftlich. Was könntest du als Nächstes tun?', '["Erklären, warum ihre Meinung falsch ist", "Sagen: „Spannende Sicht. Warum liebst du ihn so?“", "So tun, als würdest du zustimmen, damit es glatt läuft", "Sofort das Thema wechseln"]'::jsonb, 'Zeig Neugier auf ihre Begeisterung, dann bleibt ihr trotz unterschiedlicher Meinungen verbunden.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('9d4b7485-9598-45ab-9df1-95a6de8dbd91', 'de', 'Sie sagt: „Ich hab diese Woche jeden Abend lange gearbeitet.“ Was könntest du darauf sagen?', '["„Was machst du beruflich?“", "„Klingt, als hättest du dir einen Abend draußen echt verdient.“", "„Wie viele Stunden arbeitest du?“", "„Bist du müde?“"]'::jsonb, 'Eine Aussage bringt etwas ein und lädt sie ohne Druck ein, mehr zu erzählen.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('9f096c93-c6af-4940-a92a-503d7c7f4a16', 'de', 'Sie erzählt, dass ihr der neue Job schwerfällt. Du erzählst von deiner eigenen Erfahrung. Und dann?', '["„So war das bei mir auch. Na ja …“", "„Wie kommst du bisher mit der Umstellung klar?“", "„Was machst du genau?“"]'::jsonb, 'Stell den Bezug zu ihrer jetzigen Situation her, um sie nach ihrer Sicht zu fragen und die Verbindung zu vertiefen.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('9f811f6d-ea33-440c-a2f7-4e4f2eab4134', 'de', 'Sie sagt, dass sie wegen der Arbeit gestresst ist. Welche Antwort schafft eine positive Verbindung?', '["„Klingt hart. Arbeit ist brutal.“", "„Du solltest versuchen, deine Zeit besser einzuteilen.“", "„Jeder ist heutzutage gestresst.“", "„Worauf freust du dich am meisten, wenn das vorbei ist?“"]'::jsonb, 'Das lenkt ihre Stimmung sanft von Stress zu Erleichterung und Vorfreude.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('a3852cf6-c43a-47f6-95c6-432c2afa408f', 'de', 'Ihr geht zusammen, und das Gespräch wird langsamer. Was zeigt einen sauberen Neustart?', '["Eine entspannte Pause, bevor du umlenkst", "Schnelle Themenwechsel", "Fragen, ob sie sich langweilt"]'::jsonb, 'Ruhe zeigt mehr Selbstbewusstsein als Tempo.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
commit;
